const res = $input.first()?.json || {};
const trig = $('Sub-workflow Input').first()?.json || {};
const fbToken = String(trig.fallbackAccessToken || '').trim();
const fbEnabled = trig.fallbackEnabled !== false;
const fbEntitled = trig.fallbackEntitlement !== false;
let orgConfig = trig.fallbackOrgConfig && typeof trig.fallbackOrgConfig === 'object' ? trig.fallbackOrgConfig : {};
const base = {
  organizationId: trig.organizationId || null,
  userId: trig.userId || null,
  connectorId: trig.connectorId || null,
  diagnostics: { workflow: 'prism-00-context-resolver', requestId: 'ctx-' + ($execution.id || 'na') + '-' + Date.now() }
};
if (!trig.supabaseUrl) {
  return [{ json: Object.assign({}, base, { contextSource: 'fallback', degraded: false, note: 'server resolver not configured (no supabaseUrl passed) - using request-supplied context', accessToken: fbToken, enabled: fbEnabled, entitlement: fbEntitled, orgConfig }) }];
}
const hasToken = typeof res.accessToken === 'string' && res.accessToken.length > 0;
const serverOk = res && !res.error && (res.ok === true || hasToken || res.entitlement !== undefined);
if (serverOk) {
  if (res.orgConfig && typeof res.orgConfig === 'object') { orgConfig = Object.assign({}, orgConfig, res.orgConfig); }
  return [{ json: Object.assign({}, base, { contextSource: 'server', degraded: false, accessToken: hasToken ? res.accessToken : '', enabled: res.enabled !== false, entitlement: res.entitlement !== false, orgConfig, userMessage: res.userMessage || null }) }];
}
const errCode = res && (res.error === 'reauth_required' || res.statusCode === 410) ? 'reauth_required' : null;
return [{ json: Object.assign({}, base, { contextSource: 'fallback', degraded: true, reasonCode: errCode, note: 'server resolver unavailable (' + (res && (res.error || res.statusCode || 'unknown')) + ') - using request-supplied context', accessToken: fbToken, enabled: fbEnabled, entitlement: fbEntitled, orgConfig }) }];
